from collections import deque

from graph import closure


def waves(graph, targets, changed, cached):
    scope = closure(graph, targets)

    missing = [n for n in scope if n not in graph]
    if missing:
        raise ValueError("missing: " + min(missing))

    # Cycle detection over the in-scope subgraph (iterative Kahn's).
    dependents = {n: [] for n in scope}
    remaining = {}
    for n in scope:
        prereqs = set(graph[n])
        remaining[n] = len(prereqs)
        for p in prereqs:
            dependents[p].append(n)

    queue = deque([n for n in scope if remaining[n] == 0])
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in dependents[n]:
            remaining[m] -= 1
            if remaining[m] == 0:
                queue.append(m)
    if len(order) < len(scope):
        raise ValueError("cycle")

    changed_set = set(changed)
    cached_set = set(cached)

    needs = {}
    for n in order:
        needs[n] = (
            n in changed_set
            or n not in cached_set
            or any(needs[p] for p in set(graph[n]))
        )

    wave = {}
    for n in order:
        prereq_waves = [wave[p] for p in set(graph[n]) if needs[p]]
        wave[n] = max(prereq_waves) + 1 if prereq_waves else 0

    waves_map = {}
    for n in scope:
        if needs[n]:
            waves_map.setdefault(wave[n], []).append(n)

    return [sorted(waves_map[i]) for i in sorted(waves_map)]
